<script setup lang="ts">
import {computed, nextTick, onMounted, onUnmounted, ref} from 'vue';
import AttendanceFilter from './AttendanceFilter.vue';
import CopyDescription from './CopyDescription.vue';
type Filters=Record<string,string|string[]>;
type Counts={loans:number;readers:number;copies:number;records:number};
type Row=Counts&{key:string;label:string;record_id?:number;author?:string;description?:string;isbn?:string};
type Report={filters:Filters;dimension:string;totals:Counts;rows:Row[];trend:(Counts&{period:string})[];trend_unit:string;rules:string};
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>;can:(p:string)=>boolean}>();
const emit=defineEmits<{record:[id:number]}>();
const labels:Record<string,string>={kind:'Категория литературы',literature_type:'Вид литературы',specialty:'Специальность',discipline:'Дисциплина',language:'Язык',document_type:'Тип документа',branch_id:'Пункт выдачи (абонемент)',category:'Категория читателя'};
const dimensions={record:'Библиографическая запись',...labels};
function today(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Almaty',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>parts.find(x=>x.type===k)!.value).join('-');}
function defaults():Filters{return {date_from:today().slice(0,7)+'-01',date_to:today(),group_by:'record',q:'',...Object.fromEntries(Object.keys(labels).map(k=>[k,[]]))};}
const form=ref(defaults()),data=ref<Report|null>(null),options=ref<Record<string,{value:string;label:string}[]>>({});
const busy=ref(false),exporting=ref(false),error=ref(''),optionError=ref(''),offset=ref(0),metric=ref<'loans'|'readers'>('loans');
const sort=ref<'loans'|'readers'|'copies'|'label'>('loans');let generation=0;
const number=(value:number)=>new Intl.NumberFormat('ru-RU').format(value);
const clone=(value:Filters):Filters=>JSON.parse(JSON.stringify(value));
function query(value:Filters){const p=new URLSearchParams();for(const [key,v] of Object.entries(value).sort()){if(Array.isArray(v)){for(const item of v)p.append(key,item);}else if(v!==''&&v!==null)p.set(key,String(v));}return p.toString();}
const dirty=computed(()=>!!data.value&&query(form.value)!==query(data.value.filters));
const applied=computed(()=>data.value?Object.entries(labels).flatMap(([key,label])=>{const values=data.value!.filters[key];return Array.isArray(values)&&values.length?[label+': '+values.map(v=>options.value[key]?.find(o=>o.value===v)?.label||v||'Не указано').join(', ')]:[];}):[]);
const ordered=computed(()=>[...(data.value?.rows||[])].sort((a,b)=>sort.value==='label'?a.label.localeCompare(b.label,'ru'):b[sort.value]-a[sort.value]||a.label.localeCompare(b.label,'ru')));
const rows=computed(()=>ordered.value.slice(offset.value,offset.value+50));
const top=computed(()=>[...(data.value?.rows||[])].sort((a,b)=>b[metric.value]-a[metric.value]).slice(0,8));
const max=computed(()=>Math.max(1,...top.value.map(r=>r[metric.value])));
const peak=computed(()=>Math.max(1,...(data.value?.trend.map(r=>r[metric.value])||[])));
const points=computed(()=>(data.value?.trend||[]).map((r,i,all)=>({...r,x:all.length===1?400:35+i*730/Math.max(1,all.length-1),y:190-r[metric.value]/peak.value*155})));
const line=computed(()=>points.value.map(p=>p.x+','+p.y).join(' '));
function day(value:string){return value.split('-').reverse().join('.');}
async function load(){if(busy.value)return;busy.value=true;error.value='';const token=++generation,snapshot=clone(form.value);try{const r=await props.api('/statistics/circulation?'+query(snapshot));if(token===generation){data.value=r;offset.value=0;}}catch(e){if(token===generation)error.value=String(e);}finally{if(token===generation)busy.value=false;}}
async function loadOptions(){try{options.value=(await props.api('/statistics/circulation/options')).filters;optionError.value='';}catch(e){optionError.value='Не удалось загрузить варианты фильтров: '+String(e);}}
function preset(kind:string){const now=today();let from=now,to=now;const d=new Date(now+'T12:00:00Z');if(kind==='month')from=now.slice(0,7)+'-01';if(kind==='previous'){d.setUTCDate(0);to=d.toISOString().slice(0,10);from=to.slice(0,7)+'-01';}if(kind==='year')from=now.slice(0,4)+'-01-01';if(kind==='academic')from=String(d.getUTCFullYear()-(d.getUTCMonth()<8?1:0))+'-09-01';form.value.date_from=from;form.value.date_to=to;load();}
function reset(){form.value=defaults();load();}
function drill(row:Row){if(!data.value||data.value.filters.group_by==='record')return;const f=clone(data.value.filters);f[String(f.group_by)]=[row.key];f.group_by='record';form.value=f;load();}
async function page(delta:number){offset.value+=delta;await nextTick();document.getElementById('loan-statistics-table')?.scrollIntoView({block:'start'});}
async function download(format:'xlsx'|'csv'){
 if(!data.value||exporting.value)return;exporting.value=true;error.value='';const snapshot=clone(data.value.filters);
 try{const r=await fetch('/api/statistics/circulation/export?'+query(snapshot)+'&format='+format,{credentials:'same-origin'});if(!r.ok){const v=await r.json();throw Error(typeof v.detail==='string'?v.detail:'Не удалось выгрузить отчёт');}const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='Книговыдача '+snapshot.date_from+' — '+snapshot.date_to+'.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=String(e);}finally{exporting.value=false;}
}
onMounted(()=>{loadOptions();load();});onUnmounted(()=>generation++);
</script>
<template>
<section class="loan-statistics">
 <div class="page-heading"><div><div class="eyebrow">СТАТИСТИКА</div><h1>Книговыдача</h1><p>Какие книги выдавали, по каким направлениям и сколько разных читателей их брали.</p></div><div class="report-actions"><button :disabled="!data||busy||exporting" @click="download('csv')">CSV</button><button class="primary" :disabled="!data||busy||exporting" @click="download('xlsx')">{{exporting?'Выгрузка…':'Выгрузить Excel'}}</button></div></div>
 <form class="card report-filters" @submit.prevent="load">
  <h2>Параметры отчёта</h2>
  <div class="period-row"><label>Выдано с<input v-model="form.date_from" type="date" required></label><label>Выдано по<input v-model="form.date_to" type="date" required></label><label>Группировка<select v-model="form.group_by" aria-label="Группировка"><option v-for="(label,key) in dimensions" :key="key" :value="key">{{label}}</option></select></label></div>
  <div class="presets"><span>Период:</span><button type="button" :disabled="busy" @click="preset('today')">Сегодня</button><button type="button" :disabled="busy" @click="preset('month')">Этот месяц</button><button type="button" :disabled="busy" @click="preset('previous')">Прошлый месяц</button><button type="button" :disabled="busy" @click="preset('year')">Этот год</button><button type="button" :disabled="busy" @click="preset('academic')">Учебный год</button></div>
  <label class="title-search">Название, автор, ISBN или номер библиографической записи<input v-model="form.q" type="search" placeholder="Например, Қаржы" maxlength="200"></label>
  <div class="filter-grid"><AttendanceFilter v-for="(label,key) in labels" :key="key" :label="label" :model-value="form[key] as string[]" :options="options[key]||[]" @update:model-value="form[key]=$event" /></div>
  <p class="help">Специальность и дисциплина — из карточки книги. Внутри фильтра достаточно одного совпадения; разные фильтры применяются вместе. Пункт выдачи — абонемент, выбранный при оформлении выдачи. Варианты показаны по книгам, которые уже выдавались.</p>
  <p v-if="optionError" role="alert">{{optionError}} <button type="button" @click="loadOptions">Повторить</button></p>
  <div class="filter-footer"><span>{{dirty?'Параметры изменены. Нажмите «Сформировать».':'Итоги, диаграммы и выгрузка используют одни и те же фильтры.'}}</span><div><button type="button" :disabled="busy" @click="reset">Сбросить</button><button class="primary" :disabled="busy">{{busy?'Расчёт…':'Сформировать'}}</button></div></div>
 </form>
 <p v-if="error" role="alert" class="inline-error">{{error}}</p><p v-if="busy" role="status">Формируем статистику книговыдачи…</p>
 <template v-if="data">
  <div class="report-scope"><strong>Выдачи с {{day(String(data.filters.date_from))}} по {{day(String(data.filters.date_to))}}</strong><span>Время Алматы · {{data.dimension}}</span></div>
  <div v-if="applied.length||data.filters.q" class="applied"><span v-for="label in applied" :key="label">{{label}}</span><span v-if="data.filters.q">Поиск: {{data.filters.q}}</span></div>
  <div class="metrics"><article v-for="(label,key) in {loans:'Выдач экземпляров',readers:'Разных читателей',copies:'Разных экземпляров',records:'Библиографических записей'}" :key="key" class="card"><span>{{label}}</span><strong>{{number(data.totals[key])}}</strong></article></div>
  <div class="chart-heading"><h2>Использование фонда</h2><label>Показатель<select v-model="metric" aria-label="Показатель"><option value="loans">Выдачи</option><option value="readers">Разные читатели</option></select></label></div>
  <div class="charts">
   <article class="card"><h3>Динамика {{data.trend_unit==='month'?'по месяцам':'по дням'}}</h3><svg viewBox="0 0 800 225" role="img" :aria-label="'Динамика: '+(metric==='loans'?'выдачи':'читатели')"><line x1="35" x2="765" y1="190" y2="190" stroke="#d9e3ed"/><text x="35" y="20">{{number(peak)}}</text><polyline :points="line" fill="none" stroke="#008789" stroke-width="3"/><circle v-for="p in points" :key="p.period" :cx="p.x" :cy="p.y" r="3" fill="#008789"><title>{{day(p.period)}}: {{number(p[metric])}}</title></circle><text x="35" y="217">{{day(points[0]?.period||'')}}</text><text x="765" y="217" text-anchor="end">{{day(points.at(-1)?.period||'')}}</text></svg><p class="help">Повторные читатели считаются отдельно внутри каждого дня или месяца.</p></article>
   <article class="card"><h3>Наиболее востребованные · {{data.dimension.toLocaleLowerCase()}}</h3><div v-for="row in top" :key="row.key" class="bar"><div><span>{{row.label}}<small v-if="row.record_id"> · №{{row.record_id}}</small></span><strong>{{number(row[metric])}}</strong></div><div class="track"><span :style="{width:100*row[metric]/max+'%'}"></span></div></div><p v-if="!top.length" class="empty-message">За выбранный период выдач нет.</p><p v-else class="help">Показаны первые {{top.length}} групп. Полный список — в таблице.</p></article>
  </div>
  <section id="loan-statistics-table" class="card report-table">
   <div class="section-heading"><div><h2>{{data.dimension==='Библиографическая запись'?'Выдачи по книгам':'Выдачи: '+data.dimension.toLocaleLowerCase()}}</h2><p>{{number(ordered.length)}} строк · читатель учитывается один раз в каждой строке</p></div><label>Сортировка<select aria-label="Сортировка" v-model="sort" @change="offset=0"><option value="loans">Больше выдач</option><option value="readers">Больше читателей</option><option value="copies">Больше экземпляров</option><option value="label">По названию</option></select></label></div>
   <div class="table-scroll"><table><thead><tr><th>{{data.dimension}}</th><th>Выдач</th><th>Читателей</th><th>Экземпляров</th><th v-if="data.filters.group_by!=='record'">Записей</th></tr></thead><tbody><tr v-for="row in rows" :key="row.key"><th scope="row"><template v-if="row.record_id"><button v-if="can('catalog.view')" class="text-link" @click="emit('record',row.record_id)">{{row.label}}</button><strong v-else>{{row.label}}</strong><small>Запись №{{row.record_id}}<template v-if="row.author"> · {{row.author}}</template></small><details v-if="row.description"><summary>Библиографическое описание</summary><p>{{row.description}}</p><CopyDescription v-if="can('catalog.view')" :record-id="row.record_id" :api="api" /></details></template><button v-else class="text-link" :disabled="busy" @click="drill(row)" title="Показать книги этой группы">{{row.label}}</button></th><td>{{number(row.loans)}}</td><td>{{number(row.readers)}}</td><td>{{number(row.copies)}}</td><td v-if="data.filters.group_by!=='record'">{{number(row.records)}}</td></tr><tr v-if="!rows.length"><td :colspan="data.filters.group_by==='record'?4:5" class="empty-message">Выдач по выбранным параметрам нет. Измените период или фильтры.</td></tr></tbody><tfoot><tr><th>Итого без повторов</th><td>{{number(data.totals.loans)}}</td><td>{{number(data.totals.readers)}}</td><td>{{number(data.totals.copies)}}</td><td v-if="data.filters.group_by!=='record'">{{number(data.totals.records)}}</td></tr></tfoot></table></div>
   <p class="table-note">Итог рассчитан без повторов. Выдача может входить в несколько специальностей, дисциплин или языковых групп; уникальные читатели по строкам не складываются.</p>
   <div class="pagination"><span>{{ordered.length?`${offset+1}–${Math.min(offset+50,ordered.length)} из ${number(ordered.length)}`:'Нет строк'}}</span><div><button :disabled="offset===0" @click="page(-50)">← Назад</button><button :disabled="offset+50>=ordered.length" @click="page(50)">Далее →</button></div></div>
  </section>
  <details class="card report-rules"><summary>Как рассчитывается отчёт</summary><p>{{data.rules}}</p><p>Категория литературы соответствует группам отчёта «Книжный фонд». Вид литературы — значение поля 952$c; специальность — 952$j; дисциплина — 952$i. Если данных нет, строка остаётся в группе «Не указано».</p></details>
 </template>
</section>
</template>
<style scoped>
.loan-statistics{--ink:#052744;--teal:#008789}.loan-statistics .page-heading{align-items:flex-start}.report-actions,.filter-footer>div,.presets,.pagination>div{display:flex;gap:8px;flex-wrap:wrap}.report-filters{padding:24px;margin:24px 0}.report-filters h2{margin:0 0 20px}.period-row{display:grid;grid-template-columns:1fr 1fr 2fr;gap:16px}.period-row label,.title-search,.section-heading label,.chart-heading label{font-size:13px;color:#536478}.period-row input,.period-row select,.title-search input{width:100%;height:44px}.presets{align-items:center;margin:14px 0 20px}.presets>span,.help{font-size:12px;color:#708199;line-height:1.6}.presets button{font-size:12px;min-height:30px;padding:6px 12px;background:#edf4f8;border:0;box-shadow:none}.title-search{display:block;margin-bottom:18px}.filter-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.filter-footer{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid #e2e9f1;padding-top:18px;margin-top:18px}.filter-footer>span{font-size:12px;color:#708199}.report-scope,.chart-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:24px 0 16px}.report-scope>span{font-size:12px;color:#708199}.applied{display:flex;flex-wrap:wrap;gap:8px}.applied>span{font-size:12px;line-height:1.5;border:1px solid #cfe5e8;background:#f1f8f9;border-radius:8px;padding:6px 10px;overflow-wrap:anywhere}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:20px 0 28px}.metrics article{min-width:0;padding:24px;display:flex;flex-direction:column;gap:14px}.metrics span{overflow-wrap:anywhere;color:#536478;font-size:13px}.metrics strong{font-size:32px;color:var(--ink);font-variant-numeric:tabular-nums}.chart-heading label{display:flex;align-items:center;gap:10px}.chart-heading select{width:auto;margin:0}.charts{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:20px}.charts article{padding:24px;min-width:0}.charts svg{width:100%;display:block;margin:20px 0}.charts svg text{fill:#708199;font-size:13px}.charts h3{margin:0 0 20px}.bar{margin:14px 0}.bar>div:first-child{display:flex;justify-content:space-between;gap:12px;font-size:12px;margin-bottom:6px}.bar span{overflow-wrap:anywhere}.bar strong{font-variant-numeric:tabular-nums}.track{height:7px;border-radius:5px;background:#eef3f7;overflow:hidden}.track>span{display:block;height:100%;background:var(--teal);border-radius:5px}.report-table{margin:24px 0;overflow:hidden;scroll-margin-top:20px}.report-table .section-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:22px 24px}.section-heading h2{margin:0}.section-heading p{font-size:12px;margin:8px 0 0;color:#708199}.section-heading select{min-width:170px;margin-bottom:0}.table-scroll{overflow:auto}.report-table table{width:100%;min-width:680px;border-collapse:collapse}.report-table th,.report-table td{padding:15px 20px;border-bottom:1px solid #e2e9f1;font-size:13px;vertical-align:top}.report-table thead th{background:#f0f4f8;color:#536478;text-align:right}.report-table th:first-child{text-align:left}.report-table tbody th{font-weight:400;min-width:280px;max-width:700px;width:65%;overflow-wrap:anywhere}.report-table td{text-align:right;font-variant-numeric:tabular-nums}.report-table small{display:block;margin-top:6px;color:#708199;font-size:12px}.report-table details{margin-top:10px;font-size:12px;color:#536478}.report-table summary{cursor:pointer}.report-table details p{line-height:1.6}.text-link{border:0!important;background:transparent!important;box-shadow:none!important;padding:0!important;min-height:0!important;text-align:left;color:#00777a;font-weight:600;line-height:1.5}.text-link:hover{text-decoration:underline}.report-table tfoot{background:#e4eef5;font-weight:700}.table-note{padding:0 24px;font-size:12px;line-height:1.6;color:#708199}.pagination{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:18px 24px;font-size:12px;color:#708199}.report-rules{padding:22px 24px}.report-rules summary{cursor:pointer;font-weight:600;color:var(--ink)}.report-rules p{font-size:13px;line-height:1.7;color:#708199}.empty-message{padding:24px!important;text-align:center!important;color:#708199}
@media(max-width:1200px){.filter-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.charts{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:700px){.report-filters{padding:18px}.period-row,.filter-grid{grid-template-columns:1fr}.filter-footer,.report-scope,.chart-heading,.report-table .section-heading{align-items:flex-start;flex-direction:column}.metrics{gap:10px}.metrics article{padding:18px}.metrics strong{font-size:27px}.charts article{padding:18px}.pagination{padding:16px;gap:10px}.pagination button{font-size:12px;padding:8px}.report-actions{margin-top:12px}}
</style>
